"""Decodes the Empathy Studio web-SDK sources downloaded from Google Drive (base64) into reference/sdk/.
Source: Drive folder of the chat-widget repository upload (owner hazem.salah@clouding.ai, uploaded 2026-09-21).
Reference material only. Never executed by the RSG applications."""
import base64, io, os
ROOT = os.path.join(os.path.dirname(os.path.abspath(__file__)), "sdk", "rich-components")
FILES = {
"carousel.ts": "",
"carousel-card/styles.ts": "",
"carousel-card/index.ts": "",
"styles.ts": "",
"selection-list-picker/index.ts": "",
"selection-list-picker/styles.ts": "",
"grouped-list-picker/index.ts": "",
"grouped-list-picker/styles.ts": "",
"booking-confirmation/index.ts": "",
"booking-confirmation/styles.ts": "",
}
for name, b64 in FILES.items():
    path = os.path.join(ROOT, name.replace("/", os.sep))
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with io.open(path, "wb") as f:
        f.write(base64.b64decode(b64))
    print("decoded", name)
